log('=== fastsearch measurement: ' + str(len(SITES)) + ' sites ===')
def core(name):
    return re.sub(r'[^一-鿿A-Za-z0-9]', '', name or '')
def collect_fastsearch(tag):
    found = {}
    last_count, stable = -1, 0
    for i in range(20):
        time.sleep(5)
        ns = nodes(dump())
        cnt = -1
        for n in ns:
            m = re.search(r'搜索结果\s*[:：]\s*(\d+)', n['text'])
            if m: cnt = int(m.group(1))
        for n in ns:
            if n['cx'] < 330 and n['text'] and n['text'] != '全部显示':
                for s in SITES:
                    if n['text'] == s['name'] or core(n['text']) == core(s['name']):
                        found[s['key']] = s['name']
        log(f'fs {tag} poll {i}: count={cnt} sites={len(found)}')
        if cnt == last_count and cnt >= 0:
            stable += 1
            if stable >= 3: break
        else:
            stable = 0
        last_count = cnt
    return found
def back_home():
    for _ in range(4):
        if 'HomeActivity' in top(): return
        key(4); time.sleep(2)
union = {}
def poster_grid():
    ns = nodes(dump())
    cands = [n for n in ns if 200 < n['cy'] < 1150 and n['cx'] > 200
             and n['w'] > 90 and n['h'] > 120
             and ('Image' in n['cls'] or 'View' in n['cls'])]
    cands.sort(key=lambda n: (n['cy'], n['cx']))
    return cands

plan = [('热播剧集', 0), ('热播剧集', 1), ('热播剧集', 2), ('热播电影', 0), ('热播电影', 1)]
for sec, idx in plan:
    tag = f'{sec}#{idx}'
    try:
        back_home()
        tap_text(sec)
        time.sleep(7)
        grid = poster_grid()
        if len(grid) < 4:
            key(20); time.sleep(4); grid = poster_grid()  # 下滚一次再看
        if idx >= len(grid):
            log(f'fs {tag}: no poster at idx {idx} (posters={len(grid)})'); continue
        p = grid[idx]
        title = 'unknown'
        for n in nodes(dump()):
            if n['text'] and abs(n['cx'] - p['cx']) < 130 and 0 < n['cy'] - p['cy'] < 230:
                title = n['text']; break
        entered = False
        for attempt in (idx, idx + 1):
            if attempt >= len(grid): break
            q = grid[attempt]
            tap_xy(q['cx'], q['cy'])
            for w in range(10):
                time.sleep(4)
                if 'FastSearchActivity' in top(): entered = True; break
            if entered: break
            back_home(); time.sleep(3)
        if not entered:
            log(f'FSQUERY | {tag} | title={title} | FAIL no FastSearchActivity'); continue
        got = collect_fastsearch(tag)
        union.update(got)
        log(f"FSQUERY | {tag} | title={title} | sites={len(got)} | keys={','.join(sorted(got.keys()))}")
    except Exception as e:
        log(f'fs {tag} EXC: {type(e).__name__} {e}')
    back_home()
log('FS_UNION_KEYS: ' + ','.join(sorted(union.keys())))
log('FS_UNION_COUNT: ' + str(len(union)))

log('crash buffer bytes: ' + str(len(sh('logcat', '-b', 'crash', '-d').strip())))
log('=== DONE ===')
print('DONE')
